def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the two long horizontal separator lines.
    separators = []
    for r in range(h):
        c = 0
        while c < w:
            e = c + 1
            while e < w and grid[r][e] == grid[r][c]:
                e += 1
            if e - c >= 15:
                separators.append((r, grid[r][c]))
            c = e
    first, replacement = separators[0]
    second, inner_color = separators[1]
    top = first + 2  # top of the outer box (the separator is immediately above it)
    # Locate the outer box's top edge, which is a run of the separator color.
    outer_color = replacement
    left = right = None
    for r in range(first + 1, second):
        c = 0
        while c < w:
            e = c + 1
            while e < w and grid[r][e] == grid[r][c]:
                e += 1
            if grid[r][c] == outer_color and e - c >= 3:
                left, right = c, e - 1
                top = r
                break
            c = e
        if left is not None:
            break
    # The inner box is a smaller rectangle of its own color within the outer box.
    # Find its top edge.
    itop = ibottom = ileft = iright = None
    for r in range(top + 1, second):
        c = left + 1
        while c < right:
            e = c + 1
            while e < right and grid[r][e] == grid[r][c]:
                e += 1
            if grid[r][c] == inner_color and e - c >= 3:
                itop, ileft, iright = r, c, e - 1
                break
            c = e
        if itop is not None:
            break
    # Find the bottom edge of the inner box.
    for r in range(itop + 1, second):
        if all(grid[r][c] == inner_color for c in range(ileft, iright + 1)):
            ibottom = r
            break
    # Extract the interior and replace all non-zero cells with the outer color.
    result = []
    for r in range(itop + 1, ibottom):
        row = []
        for c in range(ileft + 1, iright):
            row.append(replacement if grid[r][c] != 0 else 0)
        result.append(row)
    return result
