def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find every small monochrome rectangular frame.  The background is noisy,
    # so frames are recognized by their long, solid horizontal edges.
    boxes = []
    for r in range(h):
        c = 0
        while c < w:
            e = c + 1
            while e < w and grid[r][e] == grid[r][c]:
                e += 1
            n = e - c
            color = grid[r][c]
            if color != 0 and 5 <= n <= 10:
                # A matching bottom edge and solid vertical sides identify a box.
                for b in range(r + 4, min(h, r + 10)):
                    if all(grid[b][x] == color for x in range(c, e)):
                        if all(grid[y][c] == color and grid[y][e-1] == color
                               for y in range(r, b + 1)):
                            boxes.append((r, b, c, e - 1, color))
                        break
            c = e
    # Group corresponding frames and use the fuller of the two patterns.
    groups = {}
    for box in boxes:
        groups.setdefault((box[4], box[1]-box[0], box[3]-box[2]), []).append(box)
    best_group = max(groups.values(), key=len)
    patterns = []
    for r, b, l, rr, color in best_group:
        p = [row[l+1:rr] for row in grid[r+1:b]]
        patterns.append((sum(v != 0 for row in p for v in row), p))
    source = max(patterns, key=lambda x: x[0])[1]
    # Output ink is the color of the other long separator/frame family.
    other = [box[4] for box in boxes if box[4] != best_group[0][4]]
    ink = other[0] if other else best_group[0][4]
    return [[ink if v != 0 else 0 for v in reversed(row)] for row in source]
